structure EquivalenceClass<
    X: Set<Any>,
    E: EquivalenceRelation<X>,
    x in X,
>: Set<Any> {
    laws {
        def { forall y in self |- [x y] in E; }
        from_relation { forall y in X |- [x y] in E -> y in self; }
        subset_of_X { forall y: Any |- (y in self) -> (y in X); }
    }
}
